+        let args_vec: Vec<String> = args.iter().map(|s| s.to_string()).collect();
+        self.captured_args.lock().unwrap().push(args_vec);
+        
+        // Return success for the test
+        Ok((0, String::new(), String::new()))
+    }
+}
