+    // Create 6 pages with identical ranges (full overlap among consecutive pages)
+    for (int p = 0; p < 6; ++p) {
+        std::vector<Slice> values;
+        // All values equal ensures min==max, but pages still overlap pairwise
+        std::string v = "aaaaa";
+        values.emplace_back(v.data(), v.size());
