+	"golang.stackrox.io/kube-linter/pkg/templates"
+	"golang.stackrox.io/kube-linter/pkg/templates/cel/internal/params"
+)
+
+const (
+	templateKey = "cel-expression"
+)
+
+func init() {
+	templates.Register(check.Template{
+		HumanName:   "CEL",
+		Key:         templateKey,
+		Description: "Flag objects with CEL expression",
+		SupportedObjectKinds: config.ObjectKindsDesc{
+			ObjectKinds: []string{objectkinds.Any},
+		},
+		Parameters:             params.ParamDescs,
+		ParseAndValidateParams: params.ParseAndValidate,
+		Instantiate: params.WrapInstantiateFunc(func(p params.Params) (check.Func, error) {
+			return func(ctx lintcontext.LintContext, object lintcontext.Object) []diagnostic.Diagnostic {
+				msg, err := evaluate(p.Check, object, ctx.Objects())
+				if err != nil {
+					return []diagnostic.Diagnostic{
+						{Message: fmt.Sprintf("error evaluating CEL check expression: %v", err)},
+					}
+				}
+				if msg != "" {
+					return []diagnostic.Diagnostic{
+						{Message: fmt.Sprintf("CEL check expression returned: %v", msg)},
+					}
+				}
+				return nil
+			}, nil
+		}),
+	})
+}
+
+func evaluate(check string, subject lintcontext.Object, objects []lintcontext.Object) (string, error) {
+	// Convert subject to map via JSON marshaling/unmarshaling for CEL compatibility
+	// We need to marshal the underlying K8sObject, not the lintcontext.Object
+	subjectBytes, err := json.Marshal(subject.K8sObject)
+	if err != nil {
+		return "", fmt.Errorf("failed to marshal subject: %v", err)
+	}
+	var subjectMap map[string]any
+	if err := json.Unmarshal(subjectBytes, &subjectMap); err != nil {
+		return "", fmt.Errorf("failed to unmarshal subject: %v", err)
+	}
+
+	// Convert objects to maps via JSON marshaling/unmarshaling
+	objectsMaps := make([]map[string]any, len(objects))
+	for i, obj := range objects {
+		objBytes, err := json.Marshal(obj.K8sObject)
+		if err != nil {
+			return "", fmt.Errorf("failed to marshal object %d: %v", i, err)
+		}
+		var objMap map[string]any
+		if err := json.Unmarshal(objBytes, &objMap); err != nil {
+			return "", fmt.Errorf("failed to unmarshal object %d: %v", i, err)
+		}
+		objectsMaps[i] = objMap
+	}
+
+	e, err := cel.NewEnv(
+		cel.Variable("subject", cel.MapType(cel.StringType, cel.AnyType)),
+		cel.Variable("objects", cel.ListType(cel.MapType(cel.StringType, cel.AnyType))),
+	)
+	if err != nil {
+		return "", err
+	}
+	ast, iss := e.Compile(check)
+	if iss.Err() != nil {
+		return "", iss.Err()
+	}
+	prg, err := e.Program(ast)
+	if err != nil {
+		return "", err
+	}
+	out, _, err := prg.Eval(map[string]any{
+		"subject": subjectMap,
+		"objects": objectsMaps,
+	})
+	if err != nil {
+		return "", err
+	}
+
+	o, ok := out.Value().(string)
+	if !ok {
+		return "", fmt.Errorf("expected string, got %v", out.Value())
+	}
+	return o, nil
+}
